def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007
    if n == 0:
        return 1

    chars = list(dict.fromkeys(alphabet))
    nxt: list[dict[str, int]] = [{}]
    bad = [False]

    for word in banned:
        node = 0
        for ch in word:
            if ch not in nxt[node]:
                nxt[node][ch] = len(nxt)
                nxt.append({})
                bad.append(False)
            node = nxt[node][ch]
        bad[node] = True

    trie = [dict(edges) for edges in nxt]
    fail = [0] * len(nxt)
    queue: list[int] = []

    for ch in chars:
        if ch in trie[0]:
            queue.append(trie[0][ch])
        else:
            nxt[0][ch] = 0

    head = 0
    while head < len(queue):
        node = queue[head]
        head += 1
        parent_fail = fail[node]
        for ch in chars:
            if ch in trie[node]:
                child = trie[node][ch]
                fail[child] = nxt[parent_fail][ch]
                bad[child] = bad[child] or bad[node] or bad[fail[child]]
                queue.append(child)
            else:
                nxt[node][ch] = nxt[parent_fail][ch]

    good = [state for state, is_bad in enumerate(bad) if not is_bad]
    index = {state: i for i, state in enumerate(good)}
    size = len(good)
    matrix = [[0] * size for _ in range(size)]
    for state in good:
        row = index[state]
        for ch in chars:
            dest = nxt[state][ch]
            if not bad[dest]:
                matrix[row][index[dest]] += 1

    def multiply(left: list[list[int]], right: list[list[int]]) -> list[list[int]]:
        out = [[0] * size for _ in range(size)]
        for i in range(size):
            left_row = left[i]
            out_row = out[i]
            for k in range(size):
                coeff = left_row[k]
                if coeff:
                    right_row = right[k]
                    for j in range(size):
                        val = right_row[j]
                        if val:
                            out_row[j] = (out_row[j] + coeff * val) % MOD
        return out

    result = [[1 if i == j else 0 for j in range(size)] for i in range(size)]
    base = matrix
    exp = n
    while exp:
        if exp & 1:
            result = multiply(result, base)
        base = multiply(base, base)
        exp >>= 1
    return sum(result[index[0]]) % MOD
